CREATE TABLE card_scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL REFERENCES institutions(id) ON DELETE CASCADE,uploaded_by uuid NOT NULL REFERENCES users(id),mime_type text NOT NULL CHECK (mime_type IN ('image/png','image/jpeg')),image_data bytea NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','processing','completed','review','failed')),application_student_id uuid REFERENCES application_students(id) ON DELETE SET NULL,result jsonb,error_message text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE INDEX card_scans_queue_idx ON card_scans (status,created_at);
